'use strict';
(() => {
const KEY='noir-boutique-demo-v1', clone=x=>JSON.parse(JSON.stringify(x));
let storageOK=true, S;
try {S=JSON.parse(localStorage.getItem(KEY)); if(!S||S.version!==1||!Array.isArray(S.products)||!Array.isArray(S.orders))S=clone(window.NOIR_SEED);} catch {S=clone(window.NOIR_SEED);storageOK=false;}
const cleanCopy=t=>String(t??'').replace(/\b(?:demo|simulated)\s*/gi,'').replace(/\s*\(\s*\)/g,'').trim();
for(const p of S.products)p.material=cleanCopy(p.material);
for(const o of S.orders){o.payment=cleanCopy(o.payment);o.paymentMethod=cleanCopy(o.paymentMethod);for(const e of o.events||[])e.label=cleanCopy(e.label);}
const root=document.getElementById('app'), dialogRoot=document.getElementById('dialog-root');
let selections={}, shopFilters={q:'',category:'',stock:false,sort:'featured'}, delivery='shipping', menuOpen=false, filterOpen=false, paymentMethod='card', toastTimer, lastFocus;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>'EGP '+Number(x||0).toLocaleString('en-EG',{maximumFractionDigits:0});
const date=x=>new Date(x).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const id=prefix=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
const routes=()=>{const raw=location.hash.replace(/^#\/?/,'')||'home';const [path,query]=raw.split('?');return{parts:path.split('/'),params:new URLSearchParams(query||'')};};
const user=()=>S.users.find(x=>x.id===S.session);
const product=id=>S.products.find(x=>x.id===id);
const findSku=sku=>{for(const p of S.products){const v=p.variants.find(v=>v.sku===sku);if(v)return{p,v};}return null;};
const branch=id=>S.branches.find(b=>b.id===String(id));
const heldStates=new Set(['Awaiting payment','Paid','Preparing','Ready for pickup']);
const fulfilledStates=new Set(['Shipped','Delivered','Collected']);
function held(sku,bid){return S.orders.filter(o=>heldStates.has(o.status)).reduce((n,o)=>n+o.items.filter(i=>i.sku===sku&&i.branchId===String(bid)).reduce((a,i)=>a+i.qty,0),0);}
function available(v,bid,online=true){const h=held(v.sku,bid),physical=Math.max(0,Number(v.stock[bid]||0)-h);return online?Math.max(0,Math.min(physical-Number(v.safety||0),Number(v.limit[bid]||0)-h)):physical;}
const totalAvailable=v=>S.branches.reduce((n,b)=>n+available(v,b.id),0);
const productAvailable=p=>p.variants.reduce((n,v)=>n+totalAvailable(v),0);
const svgPaths={
 search:'<circle cx="10.8" cy="10.8" r="7.3"/><path d="m16 16 4.5 4.5"/>',
 user:'<circle cx="12" cy="8" r="3.5"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 heart:'<path d="M20.8 4.8a5.5 5.5 0 0 0-7.8 0L12 6l-1-1.2a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.4a5.5 5.5 0 0 0 0-7.8Z"/>',
 pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 truck:'<path d="M1 5h13v12H1zM14 9h5l4 5v3h-9"/><circle cx="5" cy="18" r="2.5"/><circle cx="18" cy="18" r="2.5"/>',
 shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 check:'<path d="m5 12 4 4L20 5"/>',
 box:'<path d="m12 2 10 5-10 5L2 7l10-5ZM2 7v10l10 5 10-5V7M12 12v10M7 4.5l10 5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 edit:'<path d="m16 3 5 5L8 21H3v-5L16 3ZM14 5l5 5"/>',
 logout:'<path d="M9 4H4v16h5M9 12h12m-4-4 4 4-4 4"/>',
 card:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20M6 15h4"/>',
 reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',
 mail:'<rect x="2" y="4" width="20" height="16"/><path d="m2 5 10 8L22 5"/>',
 store:'<path d="M3 9h18l-2-6H5L3 9ZM4 9v12h16V9M9 21v-7h6v7"/>'
};
const icon=name=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(svgPaths[name]||svgPaths.box)+'</svg>';
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch{storageOK=false;toast('Unable to save your changes. Please try again.');}}
function log(text){S.activity.unshift({text,at:new Date().toISOString()});S.activity=S.activity.slice(0,60);}
function toast(text){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function go(path){closeDialog();if(location.hash==='#/'+path)render();else location.hash='/'+path;}
function expire(){let changed=false;for(const o of S.orders){if(o.status==='Awaiting payment'&&Date.now()>o.expiresAt){o.status='Expired';o.payment='Unpaid';o.events.push({label:'Payment hold expired; stock released',at:new Date().toISOString()});log(o.number+' expired; reservation released');changed=true;}}if(changed)save();return changed;}
function header(active){const cartCount=S.cart.reduce((n,i)=>n+i.qty,0);return '<div class="announcement">A LITTLE EXTRAORDINARY, EVERY DAY &nbsp; · &nbsp; COMPLIMENTARY SHIPPING OVER EGP 5,000</div><header class="header"><div class="wrap header-inner"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open menu" aria-expanded="'+menuOpen+'">'+icon('menu')+'</button><a class="brand" href="#/home" aria-label="Noir Boutique home">NOIR<span>BOUTIQUE</span></a><nav class="nav" aria-label="Main navigation">'+[['shop','The collection'],['sale','Sale'],['branches','Our boutiques'],['about','Our story']].map(([href,label])=>'<a href="#/'+href+'" class="'+(active===href?'active':'')+'">'+label+'</a>').join('')+'</nav><div class="header-actions"><a class="icon-button desktop-only" href="#/shop?search=1" aria-label="Search">'+icon('search')+'</a><a class="icon-button desktop-only" href="#/wishlist" aria-label="Wishlist">'+icon('heart')+'</a><a class="icon-button" href="#/'+(user()?'account':'login')+'" aria-label="My account">'+icon('user')+'</a><a class="icon-button" href="#/cart" aria-label="Shopping bag">'+icon('bag')+(cartCount?'<span class="count">'+cartCount+'</span>':'')+'</a></div></div><nav class="mobile-nav '+(menuOpen?'open':'')+'">'+[['shop','The collection'],['sale','Sale'],['branches','Our boutiques'],['wishlist','Wishlist'],['about','Our story']].map(([p,t])=>'<a href="#/'+p+'">'+t+'</a>').join('')+'</nav></header>';}
function footer(){return '<section class="newsletter"><div class="wrap newsletter-inner"><div><div class="eyebrow">Letters from Noir</div><h2>A little something, just for you.</h2><p>New arrivals, thoughtful edits, and things worth discovering.</p></div><form class="newsletter-form" data-form="newsletter"><input type="email" name="email" placeholder="Your email address" aria-label="Your email address" required><button type="submit">Join the list &nbsp; '+icon('arrow')+'</button></form></div></section><footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="#/home">NOIR<span>BOUTIQUE</span></a><p>Considered pieces. Everyday statements.<br>A boutique for your own kind of extraordinary.</p></div><div><h3>Explore</h3><div class="footer-links"><a href="#/shop">The collection</a><a href="#/sale">The sale edit</a><a href="#/branches">Our boutiques</a><a href="#/about">Our story</a></div></div><div><h3>Here to help</h3><div class="footer-links"><a href="#/contact">Contact us</a><a href="#/shipping">Shipping & pickup</a><a href="#/returns">Returns & exchanges</a><a href="#/faq">Frequently asked</a></div></div><div><h3>Your Noir</h3><div class="footer-links"><a href="#/account">My account</a><a href="#/account/orders">My orders</a><a href="#/wishlist">My wishlist</a><a href="#/privacy">Privacy</a></div></div></div><div class="footer-bottom"><span>© 2026 Noir Boutique. All rights reserved.</span><span>PREPAID ONLINE &nbsp; / &nbsp; SHIPPING & BOUTIQUE PICKUP</span></div></div></footer>';}
function shell(body,active=''){root.innerHTML=header(active)+'<main id="main" tabindex="-1">'+body+'</main>'+footer();if(!storageOK)toast('Unable to save changes. Please check your browser settings.');}
function price(p){return '<span class="price">'+money(p.price)+(p.compareAt>p.price?'<del>'+money(p.compareAt)+'</del>':'')+'</span>';}
function card(p){const count=productAvailable(p);return '<article class="product-card"><div class="product-photo '+(p.images[0].includes('spectrum')?'colorful':'')+'"><a href="#/product/'+esc(p.id)+'"><img src="'+esc(p.images[0])+'" alt="'+esc(p.name)+'" loading="lazy"></a>'+(p.badge||!count?'<span class="badge">'+esc(!count?'Sold out':p.badge)+'</span>':'')+'<button class="icon-button favorite '+(S.wishlist.includes(p.id)?'is-saved':'')+'" data-action="wish" data-id="'+esc(p.id)+'" aria-label="'+(S.wishlist.includes(p.id)?'Remove from':'Add to')+' wishlist: '+esc(p.name)+'">'+icon('heart')+'</button><button class="quick-view" data-action="quick" data-id="'+esc(p.id)+'">QUICK VIEW &nbsp; +</button></div><div class="product-info"><div class="category">'+esc(p.category)+'</div><h3 class="product-name"><a href="#/product/'+esc(p.id)+'">'+esc(p.name)+'</a></h3>'+price(p)
+'<div class="stock-note '+(!count?'out':'')+'">'+(count?'Available in '+S.branches.filter(b=>p.variants.some(v=>available(v,b.id)>0)).length+' boutiques':'Currently out of stock')+'</div></div></article>';}
const breadcrumb=t=>'<div class="wrap breadcrumb"><a href="#/home">Home</a> &nbsp; / &nbsp; '+esc(t)+'</div>';
const pageHead=(t,s='',label='NOIR BOUTIQUE')=>'<div class="wrap page-head"><div class="eyebrow">'+esc(label)+'</div><h1>'+esc(t)+'</h1><p>'+esc(s)+'</p></div>';
const empty=(t,s,label,route)=>'<div class="empty">'+icon('bag')+'<h2>'+esc(t)+'</h2><p>'+esc(s)+'</p>'+(label?'<a class="button" href="#/'+route+'">'+label+' '+icon('arrow')+'</a>':'')+'</div>';
function home(){return '<section class="hero"><div class="hero-copy"><div class="eyebrow">The everyday edit / 2026</div><h1>Not just a bag.<br>A little <em>you.</em></h1><p>Beautifully considered pieces for wherever life takes you. Find the one that feels like yours.</p><a class="button" href="#/shop">Discover the collection '+icon('arrow')+'</a><div class="hero-foot"><span>'+icon('pin')+' Four boutiques</span><span>'+icon('box')+' Collect in store</span><span>'+icon('shield')+' Prepaid checkout</span></div></div><div class="hero-image"><img src="assets/burgundy-tote.jfif" alt="Burgundy shoulder tote styled with a beige jacket"><span class="image-caption">THE EVERYDAY TOTE</span></div></section><div class="wrap perks"><div class="perk">'+icon('truck')+'<span>Complimentary shipping over EGP 5,000</span></div><div class="perk">'+icon('store')+'<span>Shop online. Collect at your boutique.</span></div><div class="perk">'+icon('pin')+'<span>Find your favorites in store</span></div></div><section class="wrap section"><div class="section-head"><div><div class="eyebrow">Your next favorite</div><h2>Good things, just arrived.</h2></div><a class="text-link" href="#/shop">Shop the collection '+icon('arrow')+'</a></div><div class="product-grid">'+S.products.filter(p=>p.enabled).map(card).join('')+'</div></section><section class="editorial"><div class="editorial-photo"><img src="assets/noir-editorial.jfif" alt="Black shoulder bag in an editorial setting" loading="lazy"></div><div class="editorial-copy"><div class="eyebrow">The art of everyday</div><h2>Some things<br>never go out<br>of <em>you.</em></h2><p>The pieces you reach for. The details that feel right. Discover modern classics with a personality of their own.</p><a class="text-link" href="#/shop?collection=Modern%20classics">Explore modern classics '+icon('arrow')+'</a></div></section><section class="wrap section"><div class="section-head"><div><div class="eyebrow">A collection for every mood</div><h2>Find your kind of Noir.</h2></div></div><div class="collection-grid">'+[['assets/burgundy-tote.jfif','The everyday edit','For the way you move.'],['assets/noir-editorial.jfif','Modern classics','Always in good company.'],['assets/spectrum-tote.jfif','Color stories','A brighter kind of everyday.']].map(([img,t,s])=>'<a class="collection-tile" href="#/shop?collection='+encodeURIComponent(t)+'"><img src="'+img+'" alt="'+t+'" loading="lazy"><div class="collection-label"><h3>'+t+'</h3><div class="row between small"><span>'+s+'</span>'+icon('arrow')+'</div></div></a>').join('')+'</div></section><section class="wrap section" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">Closer than you think</div><h2>Your Noir, in your neighborhood.</h2></div><a class="text-link" href="#/branches">Find a boutique '+icon('arrow')+'</a></div><div class="branch-art"><div><div class="eyebrow">Online meets in store</div><p class="muted small" style="margin-top:10px">Discover your favorite. Find it nearby. Pick your boutique.</p></div>'+icon('store')+'</div></section>';}
function shop(sale=false){const collection=routes().params.get('collection')||'';let ps=S.products.filter(p=>p.enabled&&(!sale||p.compareAt>p.price)&&(!collection||p.collection===collection)&&(!shopFilters.category||p.category===shopFilters.category)&&(!shopFilters.q||(p.name+' '+p.category).toLowerCase().includes(shopFilters.q.toLowerCase()))&&(!shopFilters.stock||productAvailable(p)>0));if(shopFilters.sort==='low')ps.sort((a,b)=>a.price-b.price);if(shopFilters.sort==='high')ps.sort((a,b)=>b.price-a.price);if(shopFilters.sort==='name')ps.sort((a,b)=>a.name.localeCompare(b.name));
return breadcrumb(sale?'Sale':'The collection')+pageHead(sale?'The sale edit.':collection||'Beautiful things, all in one place.',sale?'Your favorites. A little more irresistible.':'Considered pieces for your own kind of everyday.','THE COLLECTION')+'<div class="wrap"><div class="shop-toolbar"><div class="row"><button class="button light small-button" data-action="filters">'+icon('menu')+' Filters</button><span class="muted small">'+ps.length+' pieces</span></div><label class="small">Sort by <select data-filter="sort" aria-label="Sort products">'+[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['name','Name: A–Z']].map(([v,t])=>'<option value="'+v+'" '+(shopFilters.sort===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div><div class="shop-layout"><aside class="filters '+(filterOpen?'open':'')+'"><div class="filter-block"><h3>Find something lovely</h3><form data-form="search"><input class="filter-search" type="search" name="q" value="'+esc(shopFilters.q)+'" placeholder="Search the collection" aria-label="Search products"><button class="text-link icon-button small" style="margin-top:10px">Search '+icon('arrow')+'</button></form></div><div class="filter-block"><h3>Category</h3>'+['','Totes','Shoulder bags'].map(c=>'<label class="check"><input type="radio" name="category" data-filter="category" value="'+esc(c)+'" '+(shopFilters.category===c?'checked':'')+'>'+esc(c||'All pieces')+'</label>').join('')+'</div><div class="filter-block"><h3>Availability</h3><label class="check"><input type="checkbox" data-filter="stock" '+(shopFilters.stock?'checked':'')+'>In stock only</label></div><button class="text-link icon-button small" data-action="clear-filters">Clear filters</button></aside><div>'+(ps.length?'<div class="product-grid">'+ps.map(card).join('')+'</div>':empty('No pieces found.','Try another filter or discover the full collection.','Shop all','shop'))+'</div></div></div>';}
const selected=p=>p.variants[0];
function detail(p,quick=false){const v=selected(p),count=totalAvailable(v),qty=selections[p.id]?.qty||1;return '<div class="product-detail"><div class="detail-image"><img src="'+esc(p.images[0])+'" alt="'+esc(p.name)+'"></div><div class="detail-copy"><div class="eyebrow">'+esc(p.collection)+'</div><h1>'+esc(p.name)+'</h1>'+price(p)+'<p class="detail-description">'+esc(p.description)+'</p><div class="buy-row"><div class="quantity"><button data-action="product-qty" data-id="'+p.id+'" data-delta="-1" aria-label="Decrease quantity">−</button><span>'+qty+'</span><button data-action="product-qty" data-id="'+p.id+'" data-delta="1" aria-label="Increase quantity">+</button></div><button class="button" data-action="add" data-id="'+p.id+'" '+(!count?'disabled':'')+'>'+icon('bag')+' '+(count?'Add to bag':'Sold out')+'</button><button class="icon-button" data-action="wish" data-id="'+p.id+'" aria-label="Save to wishlist">'+icon('heart')+'</button></div><p class="small muted">'+(count?'Available online · prepaid payment only':'Currently unavailable online.')+'</p><div class="branch-availability"><h3>'+icon('pin')+' Find it in a boutique</h3>'+S.branches.map(b=>'<div class="branch-line"><a href="#/branches">'+esc(b.name)+'</a><span class="'+(available(v,b.id,false)?'available':'muted')+'">'+(available(v,b.id,false)?'In store · '+available(v,b.id,false)+' available':'Unavailable')+'</span></div>').join('')+'<p class="small muted" style="margin-top:12px">Choose shipping or boutique pickup at checkout.</p></div><details class="detail-accordion"><summary>Details & care</summary><p>'+esc(p.material)+'. Keep away from moisture and wipe gently with a soft cloth.</p></details><details class="detail-accordion"><summary>Shipping & boutique pickup</summary><p>Shipping is EGP 100, complimentary over EGP 5,000. Boutique pickup is free. Pay online first, then collect once your order is ready.</p></details><details class="detail-accordion"><summary>Returns & exchanges</summary><p>Visit your account to view your orders. Contact our team for help with your order.</p></details>'+(quick?'<a class="text-link" style="margin-top:18px" href="#/product/'+p.id+'">View full details '+icon('arrow')+'</a>':'')+'</div></div>';}
function productPage(pid){const p=product(pid);if(!p?.enabled)return notFound();return breadcrumb(p.name)+'<div class="wrap">'+detail(p)+'</div><section class="wrap section"><div class="section-head"><h2>In good company.</h2></div><div class="product-grid">'+S.products.filter(x=>x.enabled&&x.id!==pid).map(card).join('')+'</div></section>';}
function cartItems(){return S.cart.map(i=>({...i,...findSku(i.sku)})).filter(i=>i.p&&i.p.enabled);}
const subtotal=()=>cartItems().reduce((n,i)=>n+i.p.price*i.qty,0);
function cartPage(){const items=cartItems(),sub=subtotal();return breadcrumb('Shopping bag')+pageHead('Your lovely little collection.','A few good things, ready to go.','YOUR BAG')+'<div class="wrap page-body">'+(!items.length?empty('Your bag is taking a moment.','Find something that feels like you.','Explore the collection','shop'):'<div class="cart-layout"><div>'+items.map(i=>'<div class="cart-line"><a href="#/product/'+i.p.id+'"><img src="'+esc(i.p.images[0])+'" alt="'+esc(i.p.name)+'"></a><div><h3><a href="#/product/'+i.p.id+'">'+esc(i.p.name)+'</a></h3><p class="small muted">'+esc(i.p.category)+'</p><div class="quantity"><button data-action="cart-qty" data-sku="'+esc(i.sku)+'" data-delta="-1" aria-label="Decrease quantity">−</button><span>'+i.qty+'</span><button data-action="cart-qty" data-sku="'+esc(i.sku)+'" data-delta="1" aria-label="Increase quantity">+</button></div></div><div style="text-align:right"><span class="price">'+money(i.p.price*i.qty)+'</span><div><button class="icon-button small muted" data-action="remove" data-sku="'+esc(i.sku)+'">Remove</button></div></div></div>').join('')+'<a class="text-link" href="#/shop" style="margin-top:28px">Continue discovering '+icon('arrow')+'</a></div><aside><div class="panel"><h3>The little details</h3><p class="small muted">'+(sub>=S.settings.freeShipping?'Your bag qualifies for complimentary shipping.':'You are '+money(S.settings.freeShipping-sub)+' away from complimentary shipping.')+'</p><div class="progress-bar"><span style="width:'+Math.min(100,sub/S.settings.freeShipping*100)+'%"></span></div><div class="summary-row"><span>Subtotal</span><span>'+money(sub)+'</span></div><div class="summary-row"><span>Shipping</span><span>Calculated at checkout</span></div><div class="summary-row"><span>Boutique pickup</span><span>Complimentary</span></div><div class="summary-row total"><span>Subtotal</span><span>'+money(sub)+'</span></div><a class="button full" href="#/checkout">Continue to checkout '+icon('arrow')+'</a><p class="small muted" style="text-align:center;margin-top:14px">'+icon('shield')+' Prepaid only · no cash on delivery</p></div></aside></div>')+'</div>';}
const verification=()=>'<label class="verification"><input type="checkbox" name="verified" required><span>I am ready to continue</span></label>';
const field=(label,name,type='text',value='',extra='')=>'<div class="field"><label for="'+name+'">'+label+'</label><input id="'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>';
const shippingFee=(type,sub)=>type==='pickup'||sub>=S.settings.freeShipping?0:S.settings.shippingFee;
let checkoutDraft={};
function checkoutPage(){const u=user(),items=cartItems(),sub=subtotal();if(!items.length)return '<div class="wrap section">'+empty('Your bag is empty.','Add a piece before checking out.','Explore the collection','shop')+'</div>';if(!u)return breadcrumb('Checkout')+'<div class="wrap section">'+empty('Make yourself at home.','Sign in or create an account to keep your order history.','Sign in to continue','login?next=checkout')+'<p style="text-align:center;margin-top:20px"><a class="text-link" href="#/register?next=checkout">New here? Create an account</a></p></div>';
const eligible=S.branches.filter(b=>b[delivery==='pickup'?'pickup':'shipping']&&items.every(i=>available(i.v,b.id)>=i.qty)),address=u.addresses[0]||{};
return breadcrumb('Checkout')+pageHead('One step closer to yours.','Shipping or boutique pickup. Always paid online.','CHECKOUT')+'<div class="wrap page-body"><form class="checkout-layout" data-form="checkout"><div><h2 class="step-title"><span>1</span>Your details</h2><div class="form-grid">'+field('Full name','name','text',u.name,'required maxlength="100"')+field('Email address','email','email',u.email,'required readonly')+field('Phone number','phone','tel',u.phone,'required minlength="7" maxlength="24"')+'</div><hr class="divide"><h2 class="step-title"><span>2</span>How would you like it?</h2><div class="delivery-options">'+[['shipping','Ship to my address','Delivered to your door','truck'],['pickup','Collect in boutique','Complimentary pickup','store']].map(([value,title,sub,ic])=>'<label class="delivery-card"><input type="radio" name="delivery" value="'+value+'" '+(delivery===value?'checked':'')+'>'+icon(ic)+'<span>'+title+'<small>'+sub+'</small></span></label>').join('')+'</div>'+(delivery==='shipping'?'<div class="form-grid">'+field('Street address','street','text',address.street||'','required maxlength="180"')+field('Apartment / building','apartment','text',address.apartment||'','maxlength="100"')+'<div class="field"><label for="city">City / region</label><select name="city" id="city" required>'+['Cairo','Giza','Alexandria','North Coast','Other'].map(x=>'<option '+(address.city===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div>'+field('Delivery notes','notes','text','','maxlength="180"')+'</div><p class="small muted">Fulfilled from '+esc(eligible[0]?.name||'an available boutique')+'. One boutique fulfills the complete order.</p>':'<div class="field"><label for="pickupBranch">Choose your boutique</label><select name="pickupBranch" id="pickupBranch" required><option value="">Select a boutique</option>'+eligible.map(b=>'<option value="'+b.id+'">'+esc(b.name)+(b.address?' — '+esc(b.address):'')+'</option>').join('')+'</select></div><p class="note">Your items will be held at your selected boutique. Wait for your ready-to-collect update before visiting. Payment is made online.</p>')+(!eligible.length?'<p class="note error" style="margin-top:18px">No single boutique has your complete bag available. Reduce a quantity or remove an item to continue.</p>':'')+'<hr class="divide"><h2 class="step-title"><span>3</span>A little peace of mind</h2>'+verification()+'<label class="check"><input type="checkbox" name="terms" required>I agree to the <a class="text-link" href="#/privacy">terms</a>.</label></div><aside><div class="panel"><h3>Your order</h3>'+items.map(i=>'<div class="row" style="margin-bottom:17px"><img src="'+esc(i.p.images[0])+'" alt="'+esc(i.p.name)+'" style="width:48px;height:60px;object-fit:cover"><div style="flex:1;font-size:12px">'+esc(i.p.name)+'<div class="small muted">Quantity '+i.qty+'</div></div><span class="small">'+money(i.p.price*i.qty)+'</span></div>').join('')+'<hr class="divide"><div class="summary-row"><span>Subtotal</span><span>'+money(sub)+'</span></div><div class="summary-row"><span>'+(delivery==='pickup'?'Pickup':'Shipping')+'</span><span>'+(shippingFee(delivery,sub)?money(shippingFee(delivery,sub)):'Complimentary')+'</span></div><div class="summary-row total"><span>Total</span><span>'+money(sub+shippingFee(delivery,sub))+'</span></div><button class="button full" type="submit" '+(!eligible.length?'disabled':'')+'>Continue to payment '+icon('arrow')+'</button><p class="small muted" style="margin-top:15px;text-align:center">'+icon('shield')+' Paymob checkout</p></div></aside></form></div>';}
function authPage(register=false,reset=false){const next=routes().params.get('next')==='checkout'?'?next=checkout':'',title=reset?'A fresh start.':register?'Your Noir starts here.':'Welcome back.';
return breadcrumb(reset?'Reset password':register?'Create account':'Sign in')+'<section class="wrap auth-layout" style="margin-bottom:65px"><div class="auth-art"><img src="assets/noir-editorial.jfif" alt="Noir boutique editorial"><div class="auth-quote">A little extraordinary.<br>Entirely yours.</div></div><div class="auth-form"><div class="eyebrow">YOUR NOIR</div><h1>'+title+'</h1><p>'+(reset?'Let’s help you find your way back.':register?'Create an account and keep your favorite things close.':'Sign in for your favorites, orders, and little details.')+'</p><form data-form="'+(reset?'reset-password':register?'register':'login')+'">'+(register?field('Full name','name','text','','required minlength="2" maxlength="100"'):'')+field('Email address','email','email','','required maxlength="180"')+(reset?'':field('Password','password','password','','required minlength="4" autocomplete="'+(register?'new-password':'current-password')+'"')+(register?field('Phone number','phone','tel','','required minlength="7" maxlength="24"'):'')+verification())+'<button class="button full" type="submit">'+(reset?'Continue':register?'Create my account':'Sign in')+' '+icon('arrow')+'</button></form><div class="auth-links"><a class="text-link" href="#/'+(register||reset?'login':'register')+next+'">'+(register||reset?'Back to sign in':'Create an account')+'</a>'+(!register&&!reset?'<a class="text-link" href="#/reset-password">Forgot password?</a>':'')+'</div></div></section>';}
function statusBadge(o){return '<span class="status '+(['Cancelled','Payment failed','Expired'].includes(o.status)?'bad':o.status==='Awaiting payment'?'hold':'good')+'">'+esc(o.status)+'</span>';}
function paymentPage(oid){const o=S.orders.find(o=>o.id===oid&&o.userId===S.session);if(!o)return notFound();if(o.status!=='Awaiting payment')return orderPage(o.id,true);return breadcrumb('Payment')+'<div class="wrap"><div class="payment-wrap"><div class="panel"><div class="row between"><span class="payment-brand">paymob</span><span class="status hold">CHECKOUT</span></div><h1>Make it yours.</h1><p class="muted small">Order '+esc(o.number)+' · Noir Boutique</p><div class="summary-row total"><span>Total to pay</span><strong>'+money(o.total)+'</strong></div><p class="note">'+icon('clock')+' Your items are held for approximately '+Math.max(0,Math.ceil((o.expiresAt-Date.now())/60000))+' more minutes.</p><div class="payment-choice">'+[['card','Card','card'],['wallet','Mobile wallet','user']].map(([v,t,ic])=>'<button class="button light '+(paymentMethod===v?'active':'')+'" data-action="payment-method" data-method="'+v+'">'+icon(ic)+t+'</button>').join('')+'</div><p class="small muted" style="margin-bottom:22px">Choose your preferred payment method to complete your order.</p><button class="button full" data-action="pay" data-id="'+o.id+'">Confirm payment '+icon('arrow')+'</button><button class="button light full" style="margin-top:12px" data-action="payment-fail" data-id="'+o.id+'">Cancel payment</button><p class="small muted" style="margin-top:18px;text-align:center">Prepaid only · no cash on delivery</p></div></div></div>';}
function orderPage(oid,confirmation=false){const o=S.orders.find(o=>o.id===oid&&o.userId===S.session);if(!o)return notFound();const paid=o.payment==='Paid',cancelled=['Cancelled','Expired','Payment failed'].includes(o.status);
return breadcrumb('Order '+o.number)+'<div class="wrap page-body"><div class="'+(confirmation?'confirmation':'narrow')+'">'+(confirmation?'<div class="confirmation-icon">'+icon(paid?'check':'clock')+'</div><div class="eyebrow">THANK YOU FOR CHOOSING NOIR</div><h1>'+(paid?'Good things are on their way.':cancelled?'Your payment was cancelled.':'Your collection is waiting.')+'</h1><p class="muted">'+(paid?'Your order is confirmed. Find all the details in your account.':cancelled?'No money was charged. Your temporary reservation has been released.':'Complete your payment before the hold expires.')+'</p>':'<div class="section-head"><div><div class="eyebrow">YOUR ORDER</div><h2>'+esc(o.number)+'</h2><p class="muted small">'+date(o.createdAt)+'</p></div>'+statusBadge(o)+'</div>')+'<div class="panel"><div class="row between"><h3 style="margin-bottom:0">Order details</h3>'+statusBadge(o)+'</div><div class="timeline">'+['Order placed','Payment confirmed',o.delivery==='pickup'?'Ready for pickup':'Preparing your order',o.delivery==='pickup'?'Collected':'Delivered'].map((s,i)=>'<div class="timeline-step '+(i===0||paid&&i===1?'done':'')+'">'+s+'</div>').join('')+'</div>'+o.items.map(i=>'<div class="cart-line"><img src="'+esc(i.image)+'" alt="'+esc(i.name)+'"><div><h3>'+esc(i.name)+'</h3><p class="small muted">Quantity '+i.qty+'</p></div><span class="small">'+money(i.price*i.qty)+'</span></div>').join('')+'<div class="summary-row"><span>Subtotal</span><span>'+money(o.subtotal)+'</span></div><div class="summary-row"><span>'+(o.delivery==='pickup'?'Pickup':'Shipping')+'</span><span>'+money(o.shipping)+'</span></div><div class="summary-row total"><span>Total</span><span>'+money(o.total)+'</span></div><div class="form-grid"><div><div class="eyebrow">Delivery</div><p class="small" style="margin-top:10px">'+(o.delivery==='pickup'?'Collect from '+esc(branch(o.branchId)?.name)+'<br>'+esc(branch(o.branchId)?.address||'Address to be confirmed'):esc(o.contact.street)+'<br>'+esc(o.contact.apartment||'')+' '+esc(o.contact.city))+'</p></div><div><div class="eyebrow">Payment</div><p class="small" style="margin-top:10px">'+esc(o.payment)+(o.paymentMethod?' · '+esc(o.paymentMethod):'')+'<br>'+esc(o.contact.email)+'</p></div></div>'+(paid&&o.delivery==='pickup'?'<p class="note success" style="margin-top:22px">Pickup reference: <strong>'+esc(o.pickupCode)+'</strong>. Please wait for your ready-to-collect update before visiting.</p>':'')+'<hr class="divide"><h3 style="font-size:19px">Order updates</h3>'+o.events.map(e=>'<p class="small muted" style="margin-bottom:8px">'+date(e.at)+' · '+esc(e.label)+'</p>').join('')+'</div><div class="actions" style="margin-top:25px">'+(o.status==='Awaiting payment'?'<a class="button" href="#/payment/'+o.id+'">Complete payment</a>':'')+(!cancelled&&heldStates.has(o.status)?'<button class="button light" data-action="cancel-order" data-id="'+o.id+'">Cancel order</button>':'')+'<a class="button" href="#/account/orders">View my orders '+icon('arrow')+'</a><a class="button light" href="#/shop">Continue shopping</a></div></div></div>';}
function accountPage(tab='overview'){const u=user();if(!u)return authPage();const orders=S.orders.filter(o=>o.userId===u.id),paid=orders.filter(o=>o.payment==='Paid');let body='';
if(tab==='profile')body='<h2 style="font-size:30px;margin-bottom:25px">Your little details.</h2><form data-form="profile" class="panel">'+field('Full name','name','text',u.name,'required minlength="2" maxlength="100"')+field('Email address','email','email',u.email,'readonly')+field('Phone number','phone','tel',u.phone,'required minlength="7" maxlength="24"')+'<button class="button">Save details '+icon('arrow')+'</button></form>';
else if(tab==='addresses')body='<h2 style="font-size:30px;margin-bottom:25px">Where to find you.</h2>'+u.addresses.map((a,i)=>'<div class="address-card" style="margin-bottom:15px"><div class="row between"><h3>'+esc(a.label||'Home')+'</h3><button class="icon-button small" data-action="delete-address" data-index="'+i+'">Remove</button></div><p class="small muted">'+esc(a.street)+'<br>'+esc(a.apartment||'')+' · '+esc(a.city)+'</p></div>').join('')+'<form data-form="address" class="panel"><h3>Add an address</h3>'+field('Address label','label','text','Home','required maxlength="40"')+field('Street address','street','text','','required maxlength="180"')+field('Apartment / building','apartment','text','','maxlength="100"')+field('City / region','city','text','','required maxlength="80"')+'<button class="button">Save address</button></form>';
else{if(tab!=='orders')body='<div class="stat-grid"><div class="stat"><div class="eyebrow">Your orders</div><div class="value">'+orders.length+'</div></div><div class="stat"><div class="eyebrow">Your favorites</div><div class="value">'+S.wishlist.length+'</div></div><div class="stat"><div class="eyebrow">Total spent</div><div class="value">'+money(paid.reduce((n,o)=>n+o.total,0))+'</div></div></div>';body+='<div class="section-head"><h2 style="font-size:30px">'+(tab==='orders'?'Your order history.':'Your latest little treasures.')+'</h2></div>'+(orders.length?'<div class="table-wrap"><table><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>'+orders.slice().reverse().map(o=>'<tr><td>'+esc(o.number)+'</td><td>'+date(o.createdAt)+'</td><td>'+money(o.total)+'</td><td>'+statusBadge(o)+'</td><td><a class="text-link" href="#/order/'+o.id+'">View order</a></td></tr>').join('')+'</tbody></table></div>':empty('A story waiting to start.','Your orders will live here.','Discover the collection','shop'));}
return breadcrumb('My account')+pageHead('Hello, '+u.name.split(' ')[0]+'.','Your favorites, your orders, your own little corner of Noir.','YOUR ACCOUNT')+'<div class="wrap page-body account-layout"><aside class="account-nav">'+[['overview','Overview','user'],['orders','My orders','bag'],['profile','My details','edit'],['addresses','My addresses','pin']].map(([t,label,ic])=>'<a class="'+(t===tab?'active':'')+'" href="#/account/'+t+'">'+icon(ic)+label+'</a>').join('')+'<a href="#/wishlist">'+icon('heart')+'My wishlist</a><button data-action="logout">'+icon('logout')+'Sign out</button></aside><div>'+body+'</div></div>';}
function branchesPage(){return breadcrumb('Our boutiques')+pageHead('A little Noir, closer to you.','Find your next favorite in one of our four boutiques.','COME SAY HELLO')+'<div class="wrap page-body"><div class="branch-grid">'+S.branches.map((b,i)=>'<article class="branch-card"><div class="row between"><span class="number">0'+(i+1)+'</span>'+icon('store')+'</div><h2>'+esc(b.name)+'</h2><p>'+esc(b.address||'Address coming soon.')+'</p><div class="chips"><span class="chip">Boutique pickup</span><span class="chip">Online availability</span></div><div class="actions"><a class="button light small-button" href="#/shop">Explore the collection '+icon('arrow')+'</a>'+(b.address?'<a class="text-link" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(b.address+' Sheikh Zayed Egypt')+'" target="_blank" rel="noopener noreferrer">Directions '+icon('pin')+'</a>':'')+'</div></article>').join('')+'</div></div>';}
function contentPage(route){const content={
about:['A boutique. A point of view.','OUR STORY','<p>Noir Boutique is a place for considered pieces and everyday statements. For the bag that feels just right. For the details that make an ordinary day a little more yours.</p><h2>Good things, thoughtfully chosen.</h2><p>Discover our collection online or find your next favorite in one of our four boutiques. Browse what is available, choose delivery or pickup, and keep your story with Noir in one place.</p><div class="editorial-photo" style="min-height:450px;margin-top:35px"><img src="assets/noir-editorial.jfif" alt="Noir editorial"></div>'],
shipping:['From our boutique to you.','SHIPPING & PICKUP','<h2>Delivered to your door</h2><p>Shipping is EGP 100 and complimentary for orders of EGP 5,000 or more. The fee is shown before payment. One boutique supplies the complete order.</p><h2>Pick it up, your way</h2><p>Choose an eligible boutique at checkout. Pickup is free and payment is made online. Your order page shows your boutique and pickup reference.</p><h2>Always prepaid</h2><p>All online orders are paid before delivery or collection. Cash on delivery is unavailable.</p>'],
returns:['A little help with your order.','RETURNS & EXCHANGES','<h2>We are here to help</h2><p>Visit My Account to review your order or cancel it while it is awaiting payment or preparation.</p><h2>Returns & exchanges</h2><p>For help with a return or exchange, contact our team with your order number and the item details.</p><div class="actions" style="margin-top:25px"><a class="button" href="#/account/orders">View my orders</a><a class="button light" href="#/contact">Contact us</a></div>'],
privacy:['Your details, thoughtfully kept.','PRIVACY','<h2>Your privacy matters</h2><p>Your account brings together your contact details, saved addresses and order history.</p><h2>Keep your details up to date</h2><p>Manage your details and saved addresses from My Account.</p><h2>Here to help</h2><p>For questions about your personal information or account, contact our team.</p><a class="button" style="margin-top:25px" href="#/contact">Contact us</a>']
};const c=content[route];return breadcrumb(c[1])+pageHead(c[0],'',c[1])+'<div class="wrap page-body"><article class="content-page">'+c[2]+'</article></div>';}
function faqPage(){return breadcrumb('Frequently asked')+pageHead('A few good answers.','','HERE TO HELP')+'<div class="wrap page-body"><div class="content-page">'+[['Can I collect my order in a boutique?','Yes. Choose pickup at checkout and a boutique with your complete bag available. Pickup is complimentary and payment is made online.'],['How do I know where an item is available?','Each product page shows its availability in our boutiques.'],['Is cash on delivery available?','No. All orders are prepaid.'],['How much is shipping?','Shipping is EGP 100, complimentary on orders of EGP 5,000 or more.'],['Where are my orders?','Open My Account and My Orders to find your order details and updates.']].map(([q,a])=>'<details class="detail-accordion"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'<p style="margin-top:30px"><a class="text-link" href="#/contact">Still curious? Get in touch '+icon('arrow')+'</a></p></div></div>';}
function contactPage(){return breadcrumb('Contact')+pageHead('Let’s talk lovely things.','A question, a favorite, or a little hello.','CONTACT NOIR')+'<div class="wrap page-body contact-layout"><div><h2 style="font-size:32px;margin-bottom:22px">Always happy to help.</h2><p class="muted" style="max-width:390px">Visit a boutique for a closer look at your next favorite. Find your order details in your account.</p><div class="feature-list"><div>'+icon('store')+'Four boutiques to discover</div><div>'+icon('bag')+'Shipping and boutique pickup</div><div>'+icon('shield')+'Prepaid checkout</div></div><a class="text-link" style="margin-top:30px" href="#/branches">Find a boutique '+icon('arrow')+'</a></div><form class="panel" data-form="contact"><h3>A little note to us</h3>'+field('Your name','name','text','','required maxlength="100"')+field('Email address','email','email','','required')+'<div class="field"><label for="message">Your message</label><textarea id="message" name="message" required maxlength="2000" placeholder="What is on your mind?"></textarea></div><button class="button">Send message '+icon('arrow')+'</button></form></div>';}
function wishlistPage(){const ps=S.products.filter(p=>p.enabled&&S.wishlist.includes(p.id));return breadcrumb('Wishlist')+pageHead('The ones you love.','Keep your favorites close.','YOUR WISHLIST')+'<div class="wrap page-body">'+(ps.length?'<div class="product-grid">'+ps.map(card).join('')+'</div>':empty('Something will catch your eye.','Tap the heart on a piece you love.','Discover the collection','shop'))+'</div>';}
function notFound(){return '<div class="wrap section">'+empty('A little off the beaten path.','This page or order is unavailable.','Back to Noir','home')+'</div>';}
function render(scroll=false){expire();const {parts}=routes(),[page,pid]=parts;let body;
switch(page){case'home':body=home();break;case'shop':body=shop();break;case'sale':body=shop(true);break;case'product':body=productPage(pid);break;case'cart':body=cartPage();break;case'checkout':body=checkoutPage();break;case'login':body=authPage();break;case'register':body=authPage(true);break;case'reset-password':body=authPage(false,true);break;case'account':body=accountPage(pid);break;case'payment':body=paymentPage(pid);break;case'order':body=orderPage(pid);break;case'confirmation':body=orderPage(pid,true);break;case'branches':body=branchesPage();break;case'wishlist':body=wishlistPage();break;case'faq':body=faqPage();break;case'contact':body=contactPage();break;case'about':case'shipping':case'returns':case'privacy':body=contentPage(page);break;default:body=notFound();}
document.title=(page==='home'?'A little extraordinary':page==='product'?product(pid)?.name||'Product':page.charAt(0).toUpperCase()+page.slice(1))+' | Noir Boutique';shell(body,page);
if(page==='checkout'){const f=root.querySelector('[data-form="checkout"]');if(f)for(const [k,v]of Object.entries(checkoutDraft)){const el=f.elements.namedItem(k);if(el&&!['delivery','verified','terms'].includes(k))el.value=v;}}
if(scroll)window.scrollTo({top:0,behavior:'instant'});
}
function closeDialog(){dialogRoot.innerHTML='';root.inert=false;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function openDialog(body){lastFocus=document.activeElement;dialogRoot.innerHTML='<div class="dialog-overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="Noir Boutique" tabindex="-1"><button class="icon-button dialog-close" data-action="close-dialog" aria-label="Close">'+icon('close')+'</button>'+body+'</section></div>';root.inert=true;document.body.style.overflow='hidden';dialogRoot.querySelector('.dialog-close').focus();}
function refreshDetail(pid){if(dialogRoot.children.length)openDialog(detail(product(pid),true));else render();}
function addToCart(pid){const p=product(pid);if(!p?.enabled)return;const v=selected(p),qty=selections[pid]?.qty||1,existing=S.cart.find(i=>i.sku===v.sku),target=(existing?.qty||0)+qty;if(target>Math.min(10,totalAvailable(v)))return toast('This quantity is currently unavailable.');if(existing)existing.qty=target;else S.cart.push({sku:v.sku,qty});save();closeDialog();render();toast(p.name+' added to your bag.');}
function checkout(form){expire();const u=user();if(!u)return go('login?next=checkout');const data=Object.fromEntries(new FormData(form)),items=cartItems(),sub=subtotal();checkoutDraft=data;if(!items.length)return go('cart');if(!data.verified||!data.terms)return toast('Please complete verification and accept the terms.');
for(const o of S.orders.filter(o=>o.userId===u.id&&o.status==='Awaiting payment')){o.status='Cancelled';o.payment='Unpaid';o.events.push({label:'Replaced by a new checkout',at:new Date().toISOString()});}
const bid=data.delivery==='pickup'?String(data.pickupBranch):S.branches.find(b=>b.shipping&&items.every(i=>available(i.v,b.id)>=i.qty))?.id,b=branch(bid);
if(!b||!b[data.delivery==='pickup'?'pickup':'shipping']||!items.every(i=>i.p.enabled&&available(i.v,bid)>=i.qty)){save();toast('Your complete bag is no longer available at this boutique. Please review your bag.');render();return;}
u.phone=data.phone;const o={id:id('order'),number:'NB-'+String(S.orders.length+1).padStart(5,'0'),userId:u.id,createdAt:new Date().toISOString(),expiresAt:Date.now()+S.settings.holdMinutes*60000,status:'Awaiting payment',payment:'Unpaid',delivery:data.delivery,branchId:bid,contact:{name:data.name,email:u.email,phone:data.phone,street:data.street||'',apartment:data.apartment||'',city:data.city||'',notes:data.notes||''},subtotal:sub,shipping:shippingFee(data.delivery,sub),total:sub+shippingFee(data.delivery,sub),pickupCode:String(Math.floor(100000+Math.random()*900000)),items:items.map(i=>({sku:i.sku,productId:i.p.id,name:i.p.name,image:i.p.images[0],qty:i.qty,price:i.p.price,branchId:bid})),events:[{label:'Order placed; items reserved',at:new Date().toISOString()}]};S.orders.push(o);save();go('payment/'+o.id);}
function pay(oid,success){expire();const o=S.orders.find(o=>o.id===oid&&o.userId===S.session);if(!o||o.status!=='Awaiting payment'){toast('This payment session is no longer active.');render();return;}o.status=success?'Paid':'Payment failed';o.payment=success?'Paid':'Unpaid';o.paymentMethod=success?(paymentMethod==='card'?'Card':'Mobile wallet'):'';o.events.push({label:success?'Payment confirmed; preparing your order':'Payment cancelled; reservation released',at:new Date().toISOString()});if(success){for(const i of o.items){const c=S.cart.find(c=>c.sku===i.sku);if(c)c.qty=Math.max(0,c.qty-i.qty);}S.cart=S.cart.filter(c=>c.qty>0);checkoutDraft={};}save();go('confirmation/'+o.id);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,pid=el.dataset.id;e.preventDefault();
switch(a){
case'menu':menuOpen=!menuOpen;render();break;
case'filters':filterOpen=!filterOpen;render();break;
case'clear-filters':shopFilters={q:'',category:'',stock:false,sort:'featured'};render();break;
case'quick':{const p=product(pid);if(p?.enabled)openDialog(detail(p,true));break;}
case'close-dialog':closeDialog();break;
case'product-qty':{const p=product(pid),v=selected(p),old=selections[pid]?.qty||1;selections[pid]={qty:Math.max(1,Math.min(10,totalAvailable(v)||1,old+Number(el.dataset.delta)))};refreshDetail(pid);break;}
case'add':addToCart(pid);break;
case'wish':if(S.wishlist.includes(pid))S.wishlist=S.wishlist.filter(x=>x!==pid);else S.wishlist.push(pid);save();if(dialogRoot.children.length)toast('Your wishlist has been updated.');else render();break;
case'cart-qty':{const item=S.cart.find(i=>i.sku===el.dataset.sku),found=findSku(el.dataset.sku);if(!item||!found)break;const qty=item.qty+Number(el.dataset.delta);if(qty>Math.min(10,totalAvailable(found.v))){toast('That quantity is currently unavailable.');break;}if(qty<=0)S.cart=S.cart.filter(i=>i!==item);else item.qty=qty;save();render();break;}
case'remove':S.cart=S.cart.filter(i=>i.sku!==el.dataset.sku);save();render();break;
case'logout':S.session=null;checkoutDraft={};save();go('home');toast('You have signed out.');break;
case'delete-address':{const u=user();if(u){u.addresses.splice(Number(el.dataset.index),1);save();render();}break;}
case'payment-method':paymentMethod=el.dataset.method;render();break;
case'pay':pay(pid,true);break;
case'payment-fail':pay(pid,false);break;
case'cancel-order':{const o=S.orders.find(o=>o.id===pid&&o.userId===S.session);if(o&&heldStates.has(o.status))openDialog('<h2>Cancel this order?</h2><p>Your reserved items will be released. '+(o.payment==='Paid'?'Your order will be marked as refunded.':'No payment has been made.')+'</p><button class="button" data-action="confirm-cancel" data-id="'+o.id+'">Cancel order</button> <button class="button light" data-action="close-dialog">Keep my order</button>');break;}
case'confirm-cancel':{const o=S.orders.find(o=>o.id===pid&&o.userId===S.session);if(o&&heldStates.has(o.status)){o.status='Cancelled';o.payment=o.payment==='Paid'?'Refunded':'Unpaid';o.events.push({label:'Order cancelled; reservation released',at:new Date().toISOString()});save();closeDialog();render();toast('Order cancelled.');}break;}
}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){shopFilters[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;render();}if(el.name==='delivery'){checkoutDraft=Object.fromEntries(new FormData(el.closest('form')));delivery=el.value;render();}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const type=form.dataset.form,data=Object.fromEntries(new FormData(form));
switch(type){
case'search':shopFilters.q=data.q.trim();render();break;
case'newsletter':form.reset();toast('Thank you for your interest in Noir.');break;
case'contact':form.reset();openDialog('<div class="success-card">'+icon('mail')+'<h2>Your note looks lovely.</h2><p>Thank you for reaching out.</p><button class="button" data-action="close-dialog">Back to Noir</button></div>');break;
case'reset-password':openDialog('<h2>Need help signing in?</h2><p>Contact our team for help accessing your account.</p><a class="button" href="#/contact">Contact us</a>');break;
case'register':{const email=data.email.trim().toLowerCase();if(S.users.some(u=>u.email===email)){toast('An account with this email already exists. Sign in instead.');break;}const u={id:id('customer'),name:data.name.trim(),email,phone:data.phone.trim(),addresses:[]};S.users.push(u);S.session=u.id;checkoutDraft={};save();go(routes().params.get('next')==='checkout'?'checkout':'account');toast('Your account is ready.');break;}
case'login':{const u=S.users.find(u=>u.email===data.email.trim().toLowerCase());if(!u){toast('No account found with this email. Create an account first.');break;}S.session=u.id;checkoutDraft={};save();go(routes().params.get('next')==='checkout'?'checkout':'account');toast('Welcome back, '+u.name.split(' ')[0]+'.');break;}
case'profile':{const u=user();if(u){u.name=data.name.trim();u.phone=data.phone.trim();save();render();toast('Your details have been saved.');}break;}
case'address':{const u=user();if(u){u.addresses.push({label:data.label.trim(),street:data.street.trim(),apartment:data.apartment.trim(),city:data.city.trim()});save();render();toast('Your address has been saved.');}break;}
case'checkout':checkout(form);break;
}});
document.addEventListener('keydown',e=>{if(!dialogRoot.children.length)return;if(e.key==='Escape'){closeDialog();return;}if(e.key==='Tab'){const els=[...dialogRoot.querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
dialogRoot.addEventListener('click',e=>{if(e.target.classList.contains('dialog-overlay'))closeDialog();});
window.addEventListener('hashchange',()=>{menuOpen=false;closeDialog();render(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue);if(next?.version===1){S=next;render();}}catch{}});
setInterval(()=>{if(expire())render();},15000);
render();
})();
